    input  wire c,
    input  wire d,
    input  wire e,
    output wire [24:0] out
);

    wire [4:0] inputs;
    assign inputs = {a, b, c, d, e};

    genvar i, j;
    generate
        for (i = 0; i < 5; i = i + 1) begin : gen_i
            for (j = 0; j < 5; j = j + 1) begin : gen_j
                // index 24 corresponds to i=0, j=0 (a compared with a)
                // index 0 corresponds to i=4, j=4 (e compared with e)
                assign out[(4 - i) * 5 + (4 - j)] = ~(inputs[4 - i] ^ inputs[4 - j]);
            end
        end
    endgenerate

endmodule
